{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  }
}
import { createServer } from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { readFile } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import { extname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('.', import.meta.url));
const db = new DatabaseSync(process.env.DB_PATH || join(root, 'workboard.sqlite'));
db.exec(`
  PRAGMA journal_mode = WAL;
  CREATE TABLE IF NOT EXISTS projects (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    created_at INTEGER NOT NULL
  );
  CREATE TABLE IF NOT EXISTS tasks (
    id TEXT PRIMARY KEY,
    project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0,
    created_at INTEGER NOT NULL
  );
`);
const listProjects = db.prepare('SELECT id, name FROM projects ORDER BY created_at, rowid');
const findProject = db.prepare('SELECT id, name FROM projects WHERE id = ?');
const insertProject = db.prepare('INSERT INTO projects (id, name, created_at) VALUES (?, ?, ?)');
const listTasks = db.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE project_id = ? ORDER BY created_at, rowid');
const insertTask = db.prepare('INSERT INTO tasks (id, project_id, title, completed, created_at) VALUES (?, ?, ?, 0, ?)');
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');

const mimeTypes = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.css': 'text/css; charset=utf-8' };
const server = createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  if (req.method === 'GET' && url.pathname === '/health') {
    res.writeHead(200, { 'content-type': 'application/json; charset=utf-8' });
    res.end(JSON.stringify({ status: 'ok' }));
    return;
  }
  if (url.pathname === '/api/projects' && req.method === 'GET') {
    return json(res, 200, listProjects.all());
  }
  if (url.pathname === '/api/projects' && req.method === 'POST') {
    try {
      const body = await readJson(req);
      const name = typeof body.name === 'string' ? body.name.trim() : '';
      if (!name) return json(res, 400, { error: 'Project name is required' });
      const project = { id: randomUUID(), name };
      insertProject.run(project.id, project.name, Date.now());
      return json(res, 201, project);
    } catch {
      return json(res, 400, { error: 'Invalid request' });
    }
  }
  const projectMatch = url.pathname.match(/^\/api\/projects\/([^/]+)$/);
  if (req.method === 'GET' && projectMatch) {
    const project = findProject.get(decodeURIComponent(projectMatch[1]));
    return project ? json(res, 200, project) : json(res, 404, { error: 'Project not found' });
  }
  const tasksMatch = url.pathname.match(/^\/api\/projects\/([^/]+)\/tasks$/);
  if (tasksMatch) {
    const projectId = decodeURIComponent(tasksMatch[1]);
    if (!findProject.get(projectId)) return json(res, 404, { error: 'Project not found' });
    if (req.method === 'GET') return json(res, 200, listTasks.all(projectId).map(task => ({ ...task, completed: Boolean(task.completed) })));
    if (req.method === 'POST') {
      try {
        const body = await readJson(req);
        const title = typeof body.title === 'string' ? body.title.trim() : '';
        if (!title) return json(res, 400, { error: 'Task title is required' });
        const task = { id: randomUUID(), projectId, title, completed: false };
        insertTask.run(task.id, projectId, title, Date.now());
        return json(res, 201, task);
      } catch { return json(res, 400, { error: 'Invalid request' }); }
    }
  }
  const taskMatch = url.pathname.match(/^\/api\/projects\/([^/]+)\/tasks\/([^/]+)$/);
  if (req.method === 'PATCH' && taskMatch) {
    const projectId = decodeURIComponent(taskMatch[1]);
    const taskId = decodeURIComponent(taskMatch[2]);
    try {
      const body = await readJson(req);
      if (typeof body.completed !== 'boolean') return json(res, 400, { error: 'Invalid completion state' });
      const result = updateTask.run(body.completed ? 1 : 0, taskId, projectId);
      if (!Number(result.changes)) return json(res, 404, { error: 'Task not found' });
      return json(res, 200, { id: taskId, projectId, completed: body.completed });
    } catch { return json(res, 400, { error: 'Invalid request' }); }
  }
  if (req.method === 'GET' && (url.pathname === '/' || url.pathname.startsWith('/projects/'))) {
    return serveFile(res, 'index.html');
  }
  if (req.method === 'GET' && url.pathname.startsWith('/')) {
    const name = url.pathname.slice(1);
    if (name && !name.includes('..') && !name.includes('/')) return serveFile(res, name);
  }
  res.writeHead(404, { 'content-type': 'text/plain; charset=utf-8' });
  res.end('Not found');
});

function json(res, status, data) {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(data));
}

async function readJson(req) {
  let raw = '';
  for await (const chunk of req) raw += chunk;
  return JSON.parse(raw || '{}');
}

async function serveFile(res, name) {
  try {
    const body = await readFile(join(root, 'public', name));
    res.writeHead(200, { 'content-type': mimeTypes[extname(name)] || 'application/octet-stream' });
    res.end(body);
  } catch {
    res.writeHead(404);
    res.end('Not found');
  }
}

const port = Number(process.env.PORT || 8080);
server.listen(port, '0.0.0.0');
const listView = document.querySelector('#project-list');
const detailView = document.querySelector('#project-detail');
const projectsNode = document.querySelector('#projects');
const alertNode = document.querySelector('#form-alert');
const form = document.querySelector('#create-form');
const nameInput = document.querySelector('#project-name');
const taskForm = document.querySelector('#task-form');
const taskInput = document.querySelector('#task-title');
const taskAlert = document.querySelector('#task-alert');
const tasksNode = document.querySelector('#tasks');
const taskFilter = document.querySelector('#task-filter');
let activeProjectId = null;
let currentTasks = [];

async function request(path, options) {
  const response = await fetch(path, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Something went wrong');
  return data;
}

function showList() {
  listView.hidden = false;
  detailView.hidden = true;
  history.pushState({}, '', '/');
  loadProjects();
}

async function loadProjects() {
  const projects = await request('/api/projects');
  projectsNode.replaceChildren();
  document.querySelector('#project-count').textContent = projects.length ? String(projects.length).padStart(2, '0') : '';
  if (!projects.length) {
    const empty = document.createElement('div');
    empty.className = 'empty-state';
    empty.innerHTML = '<span class="empty-icon" aria-hidden="true">◇</span><strong>No projects yet</strong><span>Create your first project to get started.</span>';
    projectsNode.append(empty);
    return;
  }
  for (const project of projects) {
    const row = document.createElement('div');
    row.className = 'project-row';
    row.dataset.testid = 'project-row';
    const name = document.createElement('span');
    name.className = 'project-name';
    name.textContent = project.name;
    const button = document.createElement('button');
    button.className = 'open-button';
    button.type = 'button';
    button.textContent = 'Open project';
    button.addEventListener('click', () => openProject(project.id));
    row.append(name, button);
    projectsNode.append(row);
  }
}

async function openProject(id) {
  const project = await request(`/api/projects/${encodeURIComponent(id)}`);
  document.querySelector('#detail-name').textContent = project.name;
  activeProjectId = project.id;
  listView.hidden = true;
  detailView.hidden = false;
  history.pushState({}, '', `/projects/${encodeURIComponent(project.id)}`);
  await loadTasks();
}

function drawTasks() {
  tasksNode.replaceChildren();
  const filter = taskFilter.value;
  const visible = currentTasks.filter(task => filter === 'All' || (filter === 'Open' ? !task.completed : task.completed));
  if (!visible.length) {
    const empty = document.createElement('div');
    empty.className = 'task-empty';
    empty.textContent = currentTasks.length ? 'No tasks match this filter.' : 'No tasks yet.';
    tasksNode.append(empty);
  }
  for (const task of visible) {
    const row = document.createElement('div');
    row.className = 'task-row';
    row.dataset.testid = 'task-row';
    const title = document.createElement('span');
    title.className = 'task-title';
    title.textContent = task.title;
    const label = document.createElement('label');
    label.className = 'task-check';
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.checked = task.completed;
    checkbox.setAttribute('aria-label', `Complete ${task.title}`);
    checkbox.addEventListener('change', async () => {
      try {
        await request(`/api/projects/${encodeURIComponent(activeProjectId)}/tasks/${encodeURIComponent(task.id)}`, {
          method: 'PATCH', headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ completed: checkbox.checked })
        });
        task.completed = checkbox.checked;
        drawTasks();
      } catch { checkbox.checked = task.completed; }
    });
    label.append(checkbox);
    row.append(title, label);
    tasksNode.append(row);
  }
}

async function loadTasks() {
  if (!activeProjectId) return;
  currentTasks = await request(`/api/projects/${encodeURIComponent(activeProjectId)}/tasks`);
  drawTasks();
}

async function renderRoute() {
  const match = location.pathname.match(/^\/projects\/([^/]+)$/);
  if (!match) {
    listView.hidden = false;
    detailView.hidden = true;
    await loadProjects();
    return;
  }
  try {
    const project = await request(`/api/projects/${encodeURIComponent(decodeURIComponent(match[1]))}`);
    document.querySelector('#detail-name').textContent = project.name;
    activeProjectId = project.id;
    listView.hidden = true;
    detailView.hidden = false;
    await loadTasks();
  } catch {
    activeProjectId = null;
    history.replaceState({}, '', '/');
    listView.hidden = false;
    detailView.hidden = true;
    await loadProjects();
  }
}

form.addEventListener('submit', async (event) => {
  event.preventDefault();
  alertNode.hidden = true;
  try {
    await request('/api/projects', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ name: nameInput.value })
    });
    nameInput.value = '';
    await loadProjects();
  } catch (error) {
    alertNode.textContent = error.message;
    alertNode.hidden = false;
  }
});

document.querySelector('#back-button').addEventListener('click', showList);
taskForm.addEventListener('submit', async event => {
  event.preventDefault();
  taskAlert.hidden = true;
  try {
    await request(`/api/projects/${encodeURIComponent(activeProjectId)}/tasks`, {
      method: 'POST', headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ title: taskInput.value })
    });
    taskInput.value = '';
    await loadTasks();
  } catch (error) {
    taskAlert.textContent = error.message;
    taskAlert.hidden = false;
  }
});
taskFilter.addEventListener('change', drawTasks);
window.addEventListener('popstate', renderRoute);
renderRoute();
