<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Workboard</title>
  <link rel="stylesheet" href="/styles.css">
  <script type="module" src="/app.js"></script>
</head>
<body>
  <main class="shell">
    <header class="topbar"><span class="brand-mark" aria-hidden="true">W</span><span>Workboard</span></header>
    <section id="project-list" class="view" aria-labelledby="page-title">
      <div class="intro">
        <p class="eyebrow">YOUR WORKSPACE</p>
        <h1 id="page-title">Workboard</h1>
        <p class="subtitle">A clear space for your projects.</p>
      </div>
      <form id="create-form" class="create-card">
        <label for="project-name">Project name</label>
        <div class="form-row">
          <input id="project-name" name="name" type="text" autocomplete="off" placeholder="e.g. Website redesign">
          <button class="primary" type="submit">Create project <span aria-hidden="true">＋</span></button>
        </div>
        <p id="form-alert" class="alert" role="alert" hidden></p>
      </form>
      <div class="list-heading"><h2>Projects</h2><span id="project-count" class="count"></span></div>
      <div id="projects" class="project-list" aria-live="polite"></div>
    </section>
    <section id="project-detail" class="view detail" hidden>
      <button id="back-button" class="back-button" type="button"><span aria-hidden="true">←</span> Projects</button>
      <div class="detail-card"><p class="eyebrow">PROJECT</p><h1 id="detail-name"></h1></div>
      <form id="task-form" class="create-card task-form">
        <label for="task-title">Task title</label>
        <div class="form-row">
          <input id="task-title" name="title" type="text" autocomplete="off" placeholder="Add a task">
          <button class="primary" type="submit">Create task</button>
        </div>
        <p id="task-alert" class="alert" role="alert" hidden></p>
      </form>
      <div class="task-toolbar"><h2>Tasks</h2><label for="task-filter">Task filter</label>
        <select id="task-filter"><option>All</option><option>Open</option><option>Completed</option></select>
      </div>
      <div id="tasks" class="task-list" aria-live="polite"></div>
    </section>
  </main>
</body>
</html>
:root { color-scheme: light; --ink: #202621; --muted: #81877f; --green: #426d4d; --line: #e9ebe6; --paper: #fff; }
* { box-sizing: border-box; }
body { margin: 0; color: var(--ink); background: #f8f9f6; font-family: 'DM Sans', Arial, sans-serif; min-height: 100vh; }
.shell { max-width: 960px; margin: 0 auto; padding: 0 44px 80px; }
.topbar { height: 76px; display: flex; align-items: center; gap: 11px; border-bottom: 1px solid var(--line); font-family: Manrope, Arial, sans-serif; font-weight: 700; letter-spacing: -.3px; }
.brand-mark { background: #e6eee4; color: var(--green); display: grid; place-items: center; width: 31px; height: 31px; border-radius: 9px; font-weight: 800; }
.view { max-width: 680px; margin: 0 auto; }
.intro { padding: 69px 0 28px; }
.eyebrow { color: #809180; font-size: 10px; letter-spacing: 1.8px; font-weight: 700; margin: 0 0 11px; }
h1, h2, p { margin-top: 0; }
h1 { font: 700 34px/1.2 Manrope, Arial, sans-serif; letter-spacing: -1.2px; margin-bottom: 8px; }
.subtitle { color: var(--muted); margin-bottom: 0; font-size: 14px; }
.create-card { background: var(--paper); border: 1px solid var(--line); border-radius: 11px; padding: 20px; box-shadow: 0 3px 12px #252e2410; }
label { display: block; font-size: 12px; font-weight: 700; margin-bottom: 9px; }
.form-row { display: flex; gap: 10px; }
input { flex: 1; min-width: 0; height: 43px; padding: 0 13px; border: 1px solid #dfe3dc; border-radius: 6px; font: inherit; outline: none; }
input::placeholder { color: #adb2ac; }
input:focus { border-color: #78977e; box-shadow: 0 0 0 3px #426d4d18; }
button { cursor: pointer; font: 600 12px 'DM Sans', sans-serif; }
.primary { height: 43px; padding: 0 16px; color: white; background: var(--green); border: 0; border-radius: 6px; }
.primary:hover { background: #355c40; }
.primary span { font-size: 16px; margin-left: 7px; vertical-align: -1px; }
.alert { color: #a83f36; font-size: 12px; margin: 10px 0 0; }
.list-heading { display: flex; align-items: center; justify-content: space-between; margin: 32px 0 11px; }
.list-heading h2 { font: 700 15px Manrope, Arial, sans-serif; margin: 0; }
.count { color: #8e958b; font-size: 11px; }
.project-list { display: grid; gap: 9px; }
.project-row { display: flex; align-items: center; justify-content: space-between; min-height: 66px; padding: 0 16px 0 19px; border: 1px solid var(--line); border-radius: 9px; background: white; box-shadow: 0 2px 7px #252e2408; }
.project-name { font-size: 13px; font-weight: 600; overflow-wrap: anywhere; }
.open-button { padding: 8px 11px; border: 1px solid #dfe5dc; border-radius: 5px; background: #fff; color: #49634c; }
.open-button:hover { background: #f2f6f1; }
.empty-state { min-height: 132px; border: 1px dashed #dfe4dc; border-radius: 9px; display: flex; align-items: center; justify-content: center; flex-direction: column; gap: 6px; color: #8b9289; font-size: 12px; }
.empty-state strong { font-size: 13px; color: #596258; }
.empty-icon { color: #96a892; font-size: 22px; }
.detail { padding-top: 40px; }
.back-button { border: 0; background: transparent; color: #536b55; padding: 8px 0; }
.back-button span { font-size: 17px; margin-right: 7px; vertical-align: -1px; }
.detail-card { background: white; border: 1px solid var(--line); border-radius: 10px; margin-top: 28px; padding: 28px; min-height: 140px; }
.detail-card h1 { overflow-wrap: anywhere; }
.task-form { margin-top: 16px; }
.task-toolbar { display: flex; align-items: center; gap: 10px; margin: 24px 0 10px; }
.task-toolbar h2 { margin: 0 auto 0 0; font: 700 15px Manrope, Arial, sans-serif; }
.task-toolbar label { margin: 0; color: var(--muted); }
.task-toolbar select { min-width: 112px; height: 34px; padding: 0 9px; border: 1px solid #dfe3dc; border-radius: 5px; color: var(--ink); background: white; font: inherit; font-size: 12px; }
.task-list { display: grid; gap: 8px; }
.task-row { display: flex; align-items: center; justify-content: space-between; min-height: 56px; padding: 0 17px; border: 1px solid var(--line); border-radius: 8px; background: white; }
.task-title { font-size: 13px; overflow-wrap: anywhere; }
.task-check { margin: 0; }
.task-check input { width: 17px; height: 17px; accent-color: var(--green); cursor: pointer; }
.task-empty { padding: 22px; border: 1px dashed #dfe4dc; border-radius: 8px; color: var(--muted); text-align: center; font-size: 12px; }
[hidden] { display: none !important; }
@media (max-width: 600px) { .shell { padding: 0 20px 56px; } .intro { padding-top: 48px; } h1 { font-size: 29px; } .create-card { padding: 16px; } .form-row { flex-direction: column; } .primary { width: 100%; } }
